    """Return the number of vowels (a, e, i, o, u, case-insensitive) in `text`.
    The letter y is not a vowel, unless it appears surrounded by consonants,
    where it acts as the vowel of the syllable (e.g. "rhythms")."""
    vowels = set("aeiou")
    count = 0
    for i, ch in enumerate(text):
        c = ch.lower()
        if c in vowels:
            count += 1
        elif c == "y":
            # Count y only when it's in the middle of the text, surrounded by
            # consonants (acting as a syllable vowel, as in "rhythms").
            if 0 < i < len(text) - 1:
                prev = text[i - 1].lower()
                nxt = text[i + 1].lower()
                if prev not in vowels and prev != "y" and nxt not in vowels and nxt != "y":
                    count += 1
    return count
